def carry_over_existing_data(apps, schema_editor):
    """Keep what users already have: read status, inbox order, file details."""
    import os
    from django.db.models import Max

    Thread = apps.get_model('Messaging', 'Thread')
    Message = apps.get_model('Messaging', 'Message')
    ThreadParticipant = apps.get_model('Messaging', 'ThreadParticipant')
    Attachment = apps.get_model('Messaging', 'Attachment')

    # Read status: "read up to" = the newest message this mailbox had read.
    for participant in ThreadParticipant.objects.all():
        newest_read = (Message.objects.filter(thread_id=participant.thread_id, read_by=participant.mailbox_id)
                       .aggregate(t=Max('created_at'))['t'])
        if newest_read and (participant.last_read_at is None or participant.last_read_at < newest_read):
            participant.last_read_at = newest_read
            participant.save(update_fields=['last_read_at'])

    # Inbox order: newest message time (or creation time for empty threads).
    for thread in Thread.objects.all():
        newest = Message.objects.filter(thread_id=thread.pk).aggregate(t=Max('created_at'))['t']
        Thread.objects.filter(pk=thread.pk).update(last_message_at=newest or thread.created_at)

    for attachment in Attachment.objects.all():
        size = 0
        try:
            size = attachment.file.size
        except (OSError, ValueError):
            pass
        Attachment.objects.filter(pk=attachment.pk).update(
            original_name=os.path.basename(attachment.file.name)[:255], size=size)


